import { Pagination, type PaginationProps } from "@components/pagination";

import { useTable } from "../hooks/use-table";

export const TablePagination = (props: PaginationProps) => {
  const { state, getPageCount, setPageIndex } = useTable();
  const { pagination } = state;

  return (
    <Pagination
      finish={getPageCount()}
      selected={pagination.pageIndex + 1}
      onSelectedChange={(page) => setPageIndex(page - 1)}
      {...props}
    >
      {props.children || (
        <>
          <Pagination.Prev />
          <Pagination.Items />
          <Pagination.Next />
        </>
      )}
    </Pagination>
  );
};

TablePagination.displayName = "Table.Pagination";
